          <tr>
            <th scope="col" class="px-4 py-2 font-medium">User</th>
            <th scope="col" class="px-4 py-2 text-right font-medium">Notes</th>
          </tr>
        </thead>
        <tbody class="divide-y divide-slate-200">
          <tr v-for="user in data.users" :key="user.name">
            <td class="px-4 py-2 text-slate-900">{{ user.name }}</td>
            <td class="px-4 py-2 text-right tabular-nums text-slate-900">{{ user.notes }}</td>
          </tr>
        </tbody>
      </table>
    </template>
    <template v-else-if="data.name">
      <h1 class="text-3xl font-bold tracking-tight text-slate-900">Not allowed</h1>
      <p class="mt-4 text-sm">
        <NuxtLink to="/notes" class="font-medium text-indigo-600 hover:underline">All notes</NuxtLink>
      </p>
    </template>
  </main>
</template>
import { ARCHIVED_ERROR } from '#shared/types/note'

export default defineEventHandler((event) => {
  const form = isFormPost(event)
  const name = currentUser(event)
  if (!name) {
    if (form) return sendRedirect(event, '/login', 303)
    throw createError({ statusCode: 401, statusMessage: 'Not signed in' })
  }
  const id = getRouterParam(event, 'id') ?? ''
  const existing = findNote(name, id)
  if (!existing) {
    if (form) return sendRedirect(event, '/notes', 303)
    throw createError({ statusCode: 404, statusMessage: 'Note not found' })
  }
  if (existing.archived) {
    if (form) return sendRedirect(event, '/archive', 303)
    throw createError({ statusCode: 409, statusMessage: ARCHIVED_ERROR, data: { code: 'archived' } })
  }
  const note = setArchived(name, id, true)
  if (form) return sendRedirect(event, '/notes', 303)
  return note
})
import { ARCHIVED_ERROR } from '#shared/types/note'

export default defineEventHandler((event) => {
  const form = isFormPost(event)
  const name = currentUser(event)
  if (!name) {
    if (form) return sendRedirect(event, '/login', 303)
    throw createError({ statusCode: 401, statusMessage: 'Not signed in' })
  }
  const id = getRouterParam(event, 'id') ?? ''
  if (findNote(name, id)?.archived) {
    if (form) return sendRedirect(event, '/archive', 303)
    throw createError({ statusCode: 409, statusMessage: ARCHIVED_ERROR, data: { code: 'archived' } })
  }
  const removed = deleteNote(name, id)
  if (form) return sendRedirect(event, '/notes', 303)
  if (!removed) throw createError({ statusCode: 404, statusMessage: 'Note not found' })
  return { removed }
})
import { ARCHIVED_ERROR, NOTE_MAX_LENGTH } from '#shared/types/note'

export default defineEventHandler(async (event) => {
  const form = isFormPost(event)
  const name = currentUser(event)
  if (!name) {
    if (form) return sendRedirect(event, '/login', 303)
    throw createError({ statusCode: 401, statusMessage: 'Not signed in' })
  }
  const id = getRouterParam(event, 'id') ?? ''
  const body = await readBody<{ title?: unknown; action?: unknown }>(event)
  // The Cancel button submits the same form without JavaScript.
  if (form && body?.action === 'cancel') return sendRedirect(event, '/notes', 303)
  const existing = findNote(name, id)
  if (!existing) {
    if (form) return sendRedirect(event, '/notes', 303)
    throw createError({ statusCode: 404, statusMessage: 'Note not found' })
  }
  if (existing.archived) {
    if (form) return sendRedirect(event, '/archive', 303)
    throw createError({ statusCode: 409, statusMessage: ARCHIVED_ERROR, data: { code: 'archived' } })
  }
  const fail = (code: string) => sendRedirect(event, `/notes?edit=${encodeURIComponent(id)}&editError=${code}`, 303)
  const title = typeof body?.title === 'string' ? body.title.trim() : ''
  if (title.length < 1) {
    if (form) return fail('invalid')
    throw createError({ statusCode: 400, statusMessage: `Note must be 1-${NOTE_MAX_LENGTH} characters`, data: { code: 'invalid' } })
  }
  if (title.length > NOTE_MAX_LENGTH) {
    if (form) return fail('too-long')
    throw createError({ statusCode: 400, statusMessage: `Use at most ${NOTE_MAX_LENGTH} characters`, data: { code: 'too-long' } })
  }
  if (noteExists(name, title, id)) {
    if (form) return fail('duplicate')
    throw createError({ statusCode: 409, statusMessage: 'You already have a note with this title' })
  }
  const note = renameNote(name, id, title)
  if (form) return sendRedirect(event, '/notes', 303)
  return note
})
import { ARCHIVED_ERROR } from '#shared/types/note'

export default defineEventHandler(async (event) => {
  const form = isFormPost(event)
  const name = currentUser(event)
  if (!name) {
    if (form) return sendRedirect(event, '/login', 303)
    throw createError({ statusCode: 401, statusMessage: 'Not signed in' })
  }
  const body = await readBody<{ pinned?: unknown }>(event)
  const pinned = body?.pinned === true || body?.pinned === 'true'
  const id = getRouterParam(event, 'id') ?? ''
  if (findNote(name, id)?.archived) {
    if (form) return sendRedirect(event, '/archive', 303)
    throw createError({ statusCode: 409, statusMessage: ARCHIVED_ERROR, data: { code: 'archived' } })
  }
  const note = setPinned(name, id, pinned)
  if (form) return sendRedirect(event, '/notes', 303)
  if (!note) throw createError({ statusCode: 404, statusMessage: 'Note not found' })
  return note
})
export default defineEventHandler((event) => {
  const form = isFormPost(event)
  const name = currentUser(event)
  if (!name) {
    if (form) return sendRedirect(event, '/login', 303)
    throw createError({ statusCode: 401, statusMessage: 'Not signed in' })
  }
  const id = getRouterParam(event, 'id') ?? ''
  const existing = findNote(name, id)
  if (!existing) {
    if (form) return sendRedirect(event, '/archive', 303)
    throw createError({ statusCode: 404, statusMessage: 'Note not found' })
  }
  if (!existing.archived) {
    if (form) return sendRedirect(event, '/archive', 303)
    throw createError({ statusCode: 409, statusMessage: 'Note is not archived', data: { code: 'not-archived' } })
  }
  const note = setArchived(name, id, false)
  if (form) return sendRedirect(event, '/archive', 303)
  return note
})
import { ARCHIVED_ERROR, BODY_MAX_LENGTH, NOTE_MAX_LENGTH, type NoteSaveErrors } from '#shared/types/note'

/** Saves title and body from a note's page; nothing is saved unless both are valid. */
export default defineEventHandler(async (event) => {
  const form = isFormPost(event)
  const name = currentUser(event)
  if (!name) {
    if (form) return sendRedirect(event, '/login', 303)
    throw createError({ statusCode: 401, statusMessage: 'Not signed in' })
  }
  const id = getRouterParam(event, 'id') ?? ''
  const existing = findNote(name, id)
  if (!existing) {
    if (form) return sendRedirect(event, '/notes', 303)
    throw createError({ statusCode: 404, statusMessage: 'Note not found' })
  }
  const page = `/notes/${existing.number}`
  if (existing.archived) {
    if (form) return sendRedirect(event, page, 303)
    throw createError({ statusCode: 409, statusMessage: ARCHIVED_ERROR, data: { code: 'archived' } })
  }
  const input = await readBody<{ title?: unknown; body?: unknown }>(event)
  const rawTitle = typeof input?.title === 'string' ? input.title : ''
  // Browsers send line breaks as CRLF; count each as one character, like `maxlength` does.
  const rawBody = typeof input?.body === 'string' ? input.body.replace(/\r\n?/g, '\n') : ''
  const title = rawTitle.trim()
  const body = rawBody.trim()
  const errors: NoteSaveErrors = {}
  if (title.length < 1) errors.title = 'empty'
  else if (title.length > NOTE_MAX_LENGTH) errors.title = 'too-long'
  else if (noteExists(name, title, id)) errors.title = 'duplicate'
  if (body.length > BODY_MAX_LENGTH) errors.body = 'too-long'
  if (errors.title || errors.body) {
    if (form) {
      setNoteFlash(event, id, { title: rawTitle, body: rawBody, errors })
      return sendRedirect(event, page, 303)
    }
    throw createError({ statusCode: 400, statusMessage: 'Invalid note', data: { errors } })
  }
  const note = updateNote(name, id, title, body)
  if (form) {
    setNoteFlash(event, id, { saved: true })
    return sendRedirect(event, page, 303)
  }
  return note
})
import { ARCHIVED_ERROR, NAME_PATTERN, SHARE_NAME_ERROR, SHARE_SELF_ERROR } from '#shared/types/note'

/** Gives another user read access; only the owner may share, and only notes on their list. */
export default defineEventHandler(async (event) => {
  const form = isFormPost(event)
  const name = currentUser(event)
  if (!name) {
    if (form) return sendRedirect(event, '/login', 303)
    throw createError({ statusCode: 401, statusMessage: 'Not signed in' })
  }
  const id = getRouterParam(event, 'id') ?? ''
  const existing = findNote(name, id)
  if (!existing) {
    if (form) return sendRedirect(event, '/notes', 303)
    throw createError({ statusCode: 404, statusMessage: 'Note not found' })
  }
  if (existing.archived) {
    if (form) return sendRedirect(event, '/archive', 303)
    throw createError({ statusCode: 409, statusMessage: ARCHIVED_ERROR, data: { code: 'archived' } })
  }
  const body = await readBody<{ name?: unknown }>(event)
  const recipient = typeof body?.name === 'string' ? body.name.trim() : ''
  const fail = (code: string) => sendRedirect(event, `/notes?share=${encodeURIComponent(id)}&shareError=${code}`, 303)
  if (!NAME_PATTERN.test(recipient)) {
    if (form) return fail('invalid')
    throw createError({ statusCode: 400, statusMessage: SHARE_NAME_ERROR, data: { code: 'invalid' } })
  }
  if (sameUser(name, recipient)) {
    if (form) return fail('self')
    throw createError({ statusCode: 400, statusMessage: SHARE_SELF_ERROR, data: { code: 'self' } })
  }
  shareNote(name, id, recipient)
  if (form) return sendRedirect(event, '/notes', 303)
  return { id, sharedWith: sharedWith(id) }
})
/** Removes one user's access; only the owner may unshare. */
export default defineEventHandler(async (event) => {
  const form = isFormPost(event)
  const name = currentUser(event)
  if (!name) {
    if (form) return sendRedirect(event, '/login', 303)
    throw createError({ statusCode: 401, statusMessage: 'Not signed in' })
  }
  const id = getRouterParam(event, 'id') ?? ''
  const body = await readBody<{ name?: unknown }>(event)
  const recipient = typeof body?.name === 'string' ? body.name.trim() : ''
  const removed = unshareNote(name, id, recipient)
  if (form) return sendRedirect(event, '/notes', 303)
  if (!removed) throw createError({ statusCode: 404, statusMessage: 'Note not found' })
  return { id, sharedWith: sharedWith(id) }
})
/** `Delete selected` / `Archive selected`: acts on the checked notes; with none checked it does nothing. */
export default defineEventHandler(async (event) => {
  const form = isFormPost(event)
  const name = currentUser(event)
  if (!name) {
    if (form) return sendRedirect(event, '/login', 303)
    throw createError({ statusCode: 401, statusMessage: 'Not signed in' })
  }
  const body = await readBody<{ action?: unknown; ids?: unknown }>(event)
  const raw = body?.ids
  const ids = (Array.isArray(raw) ? raw : raw === undefined ? [] : [raw]).filter((id): id is string => typeof id === 'string')
  const action = body?.action
