  if (body.length > BODY_MAX_LENGTH) errors.body = 'too-long'
  if (errors.title || errors.body) {
    if (form) {
      setNoteFlash(event, id, { title: rawTitle, body: rawBody, errors })
      return sendRedirect(event, page, 303)
    }
    throw createError({ statusCode: 400, statusMessage: 'Invalid note', data: { errors } })
  }
  const note = updateNote(name, id, title, body)
  if (form) {
    setNoteFlash(event, id, { saved: true })
    return sendRedirect(event, page, 303)
  }
  return note
})
import { ARCHIVED_ERROR, NAME_PATTERN, SHARE_NAME_ERROR, SHARE_SELF_ERROR } from '#shared/types/note'

/** Gives another user read access; only the owner may share, and only notes on their list. */
export default defineEventHandler(async (event) => {
  const form = isFormPost(event)
  const name = currentUser(event)
  if (!name) {
    if (form) return sendRedirect(event, '/login', 303)
    throw createError({ statusCode: 401, statusMessage: 'Not signed in' })
  }
  const id = getRouterParam(event, 'id') ?? ''
  const existing = findNote(name, id)
  if (!existing) {
    if (form) return sendRedirect(event, '/notes', 303)
    throw createError({ statusCode: 404, statusMessage: 'Note not found' })
  }
  if (existing.archived) {
    if (form) return sendRedirect(event, '/archive', 303)
    throw createError({ statusCode: 409, statusMessage: ARCHIVED_ERROR, data: { code: 'archived' } })
  }
  const body = await readBody<{ name?: unknown }>(event)
  const recipient = typeof body?.name === 'string' ? body.name.trim() : ''
  const fail = (code: string) => sendRedirect(event, `/notes?share=${encodeURIComponent(id)}&shareError=${code}`, 303)
  if (!NAME_PATTERN.test(recipient)) {
    if (form) return fail('invalid')
    throw createError({ statusCode: 400, statusMessage: SHARE_NAME_ERROR, data: { code: 'invalid' } })
  }
  if (sameUser(name, recipient)) {
    if (form) return fail('self')
    throw createError({ statusCode: 400, statusMessage: SHARE_SELF_ERROR, data: { code: 'self' } })
  }
  shareNote(name, id, recipient)
  if (form) return sendRedirect(event, '/notes', 303)
  return { id, sharedWith: sharedWith(id) }
})
/** Removes one user's access; only the owner may unshare. */
export default defineEventHandler(async (event) => {
  const form = isFormPost(event)
  const name = currentUser(event)
  if (!name) {
    if (form) return sendRedirect(event, '/login', 303)
    throw createError({ statusCode: 401, statusMessage: 'Not signed in' })
  }
  const id = getRouterParam(event, 'id') ?? ''
  const body = await readBody<{ name?: unknown }>(event)
  const recipient = typeof body?.name === 'string' ? body.name.trim() : ''
  const removed = unshareNote(name, id, recipient)
  if (form) return sendRedirect(event, '/notes', 303)
  if (!removed) throw createError({ statusCode: 404, statusMessage: 'Note not found' })
  return { id, sharedWith: sharedWith(id) }
})
/** `Delete selected` / `Archive selected`: acts on the checked notes; with none checked it does nothing. */
export default defineEventHandler(async (event) => {
  const form = isFormPost(event)
  const name = currentUser(event)
  if (!name) {
    if (form) return sendRedirect(event, '/login', 303)
    throw createError({ statusCode: 401, statusMessage: 'Not signed in' })
  }
  const body = await readBody<{ action?: unknown; ids?: unknown }>(event)
  const raw = body?.ids
  const ids = (Array.isArray(raw) ? raw : raw === undefined ? [] : [raw]).filter((id): id is string => typeof id === 'string')
  const action = body?.action
  if (action !== 'delete' && action !== 'archive') {
    if (form) return sendRedirect(event, '/notes', 303)
    throw createError({ statusCode: 400, statusMessage: 'Unknown action' })
  }
  const count = ids.length ? (action === 'delete' ? deleteNotes(name, ids) : archiveNotes(name, ids)) : 0
  if (form) return sendRedirect(event, '/notes', 303)
  return { action, count }
})
import { NOTE_MAX_LENGTH, RATE_LIMIT_ERROR } from '#shared/types/note'

export default defineEventHandler(async (event) => {
  const form = isFormPost(event)
  const name = currentUser(event)
  if (!name) {
    if (form) return sendRedirect(event, '/login', 303)
    throw createError({ statusCode: 401, statusMessage: 'Not signed in' })
  }
  // `text` is the field's old name; still accepted from pages and clients loaded before the rename.
  const body = await readBody<{ title?: unknown; text?: unknown }>(event)
  const raw = body?.title ?? body?.text
  const title = typeof raw === 'string' ? raw.trim() : ''
  if (title.length < 1) {
    if (form) return sendRedirect(event, '/notes?error=invalid', 303)
    throw createError({ statusCode: 400, statusMessage: `Note must be 1-${NOTE_MAX_LENGTH} characters`, data: { code: 'invalid' } })
  }
  if (title.length > NOTE_MAX_LENGTH) {
    if (form) return sendRedirect(event, '/notes?error=too-long', 303)
    throw createError({ statusCode: 400, statusMessage: `Use at most ${NOTE_MAX_LENGTH} characters`, data: { code: 'too-long' } })
  }
  if (noteExists(name, title)) {
    if (form) return sendRedirect(event, '/notes?error=duplicate', 303)
    throw createError({ statusCode: 409, statusMessage: 'You already have a note with this title' })
  }
  // Checked last, so rejected adds never count; nothing awaits between this check and the add.
  const retryAfter = addRetryAfter(name)
  if (retryAfter) {
    setResponseHeader(event, 'Retry-After', retryAfter)
    if (form) return sendRedirect(event, '/notes?error=rate-limited', 303)
    throw createError({ statusCode: 429, statusMessage: RATE_LIMIT_ERROR, data: { code: 'rate-limited' } })
  }
  const note = addNote(name, title)
  if (form) return sendRedirect(event, '/notes', 303)
  setResponseStatus(event, 201)
  return note
})
export default defineEventHandler((event) => {
  const form = isFormPost(event)
  const name = currentUser(event)
  if (!name) {
    if (form) return sendRedirect(event, '/login', 303)
    throw createError({ statusCode: 401, statusMessage: 'Not signed in' })
  }
  const note = undoDelete(name)
  if (form) return sendRedirect(event, '/notes', 303)
  if (!note) throw createError({ statusCode: 404, statusMessage: 'Nothing to undo' })
  return note
})
export default defineEventHandler((event) => {
  const name = currentUser(event)
  if (!name) return sendRedirect(event, '/login', 303)
  deleteAccount(name)
  signOut(event)
  return sendRedirect(event, '/login?deleted=1', 303)
})
import { NAME_PATTERN } from '#shared/types/note'

export default defineEventHandler(async (event) => {
  const body = await readBody<{ name?: unknown }>(event)
  const name = typeof body?.name === 'string' ? body.name.trim() : ''
  if (!NAME_PATTERN.test(name)) {
    if (isFormPost(event)) return sendRedirect(event, '/login?error=invalid', 303)
    throw createError({ statusCode: 400, statusMessage: 'Name must be 2-20 letters' })
  }
  signIn(event, name)
  if (isFormPost(event)) return sendRedirect(event, '/notes', 303)
  return { name }
})

