import { isAdmin } from '#shared/types/note'

/** Makes another user's account read-only (`readOnly: true`) or writable again; only the admin may, and never for `admin`. */
export default defineEventHandler(async (event) => {
  const form = isFormPost(event)
  const name = currentUser(event)
  if (!name) {
    if (form) return sendRedirect(event, '/login', 303)
    throw createError({ statusCode: 401, statusMessage: 'Not signed in' })
  }
  if (!isAdmin(name)) {
    if (form) return sendRedirect(event, '/admin', 303)
    throw createError({ statusCode: 403, statusMessage: 'Forbidden' })
  }
  const body = await readBody<{ name?: unknown; readOnly?: unknown }>(event)
  const user = typeof body?.name === 'string' ? body.name.trim() : ''
  const readOnly = body?.readOnly === true || body?.readOnly === 'true'
  if (!user || isAdmin(user) || !userExists(user)) {
    if (form) return sendRedirect(event, '/admin', 303)
    throw createError({ statusCode: isAdmin(user) ? 400 : 404, statusMessage: isAdmin(user) ? 'The admin account stays writable' : 'User not found' })
  }
  setReadOnly(user, readOnly)
  if (form) return sendRedirect(event, '/admin', 303)
  return { name: user, readOnly }
})
EOF
