const titleError = computed(() => (errors.value.title ? SAVE_MESSAGES.title[errors.value.title] : ''))
const bodyError = computed(() => (errors.value.body ? SAVE_MESSAGES.body[errors.value.body] : ''))

async function save() {
  const current = note.value
  if (saving.value || !current) return
  saving.value = true
  saved.value = false
  readOnlyError.value = false
  try {
    const updated = await $fetch<Note>(`/api/notes/${current.id}/save`, {
      method: 'POST',
      body: { title: editTitle.value, body: editBody.value },
    })
    data.value = { ...data.value, note: updated, flash: null }
    editTitle.value = updated.title
    editBody.value = updated.body
    errors.value = {}
    saved.value = true
  } catch (error) {
    const { statusCode: status, data: body } = error as { statusCode?: number; data?: { data?: { errors?: NoteSaveErrors } } }
    if (status === 401) return navigateTo('/login')
    if ((body as { data?: { code?: string } } | undefined)?.data?.code === 'read-only') readOnlyError.value = true
    else if (body?.data?.errors) errors.value = body.data.errors
    else {
      // Archived or deleted meanwhile: show the note as the server has it now.
      errors.value = {}
      data.value = await $fetch<NoteResponse>(`/api/notes/number/${encodeURIComponent(String(route.params.number))}`)
    }
  } finally {
    saving.value = false
  }
}
</script>

